"""Unit 41: Tagalog Basic Course, Semester I, Chapter 13, Lesson 1: Education.
Original lessons; the scope follows the DLIFLC Tagalog Basic Course (piloting edition, June 2017).
Pictures, audio, partner work and role plays are left out; the book's answer keys are used (misprints noted).
Numbers, percentages and dates are written in words in the spoken lines."""
from dsl_tl import *


def dd(xs, ans, n=3, extra=()):
    out = []
    for x in list(xs) + list(extra):
        if x != ans and x not in out:
            out.append(x)
    return out[:n]


def P(rows):
    return [(t, e) for _, t, e in rows]


def _ass(root):
    c = root[0].lower()
    if c in "dlrst":
        return "n"
    if c in "bp":
        return "m"
    return "ng"


def kasing(root):
    return "kasi" + _ass(root) + root


def magkasing(root):
    return "magkasi" + _ass(root) + root


def magkakasing(root):
    return "magkakasi" + _ass(root) + root


