# ------------------------------------------------------------------ 4 pa-an/han/nan nouns
_PAN = [["antas", "level", "pamantasan", "university"], ["aral", "study", "paaralan", "school"], ["mamahala", "to govern", "pamahalaan", "government"], ["hayag", "to announce, make known", "pahayagan", "newspaper"], ["puno", "lead, leader", "pamunuan", "leadership"]]
