        + [M("What is the structure of pa-an/han/nan nouns?", "pa + root word + an/han/nan", ["um + root word", "mag + root word", "root word + in"], "pa + ugat + an."), M("What can a pa-an/han/nan noun name?", "the place where the action of the root happens", ["only a person", "only a time", "only a color"], "lugar."), M("What else can they express?", "a contest or competition", ["a command", "a question", "a plural"], "paligsahan."), M("What happens to a root ending in d before an/han/nan?", "d changes to r", ["d is doubled", "d is dropped", "nothing"], "d to r."), M("What does patalbugan refer to?", "a colloquial contest", ["a school", "a market", "a hospital"], "patalbugan.")]
        + [F("May pribado at pampublikong ___. (school)", "paaralan", ["pahayagan", "pamunuan"], "paaralan."), F("Sinusuportahan ito ng lokal na ___. (government)", "pamahalaan", ["pamantasan", "pamayanan"], "pamahalaan."), F("Nasa ___ kanina ang balita. (newspaper)", "pahayagan", ["palaruan", "pamilihan"], "pahayagan."), F("Malayo ang ___ sa bahay namin. (playground)", "palaruan", ["pamahalaan", "pamunuan"], "palaruan.")]
